package io.tenvyr.control.authority;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import io.tenvyr.platform.domain.Approval;
import java.sql.*;
import java.time.Instant;
import java.util.*;
import java.util.function.Predicate;

/** Terminal approval decisions and same-attempt resume commit with budget and outbox authority. */
public final class ApprovalService {
    @FunctionalInterface public interface WorkspaceMetadata {JsonNode get(Connection c,String execution)throws Exception;}
    private final Db db;private final BudgetLedgerService budget;private final PlanProposalService plans;private Predicate<String> supportsObserved;private WorkspaceMetadata workspaceMetadata;
    public ApprovalService(Db db,BudgetLedgerService budget,PlanProposalService plans){this.db=db;this.budget=budget;this.plans=plans;}
    public void bindRuntime(Predicate<String> supports,WorkspaceMetadata metadata){supportsObserved=supports;workspaceMetadata=metadata;}
    private <T>T tx(Connection c,Db.Work<T> work){return c==null?db.transaction(work):Db.on(c).transaction(work);}
    public ObjectNode request(JsonNode p,Connection c,long expiry){return tx(c,t->request(t,p,Instant.now(),expiry));}
    public static ObjectNode request(Db t,JsonNode p,Instant now,long expiry){Instant due=Approval.approvalExpiry(now,expiry);JsonNode s=p.path("scope"),target=p.path("target");t.execute("INSERT INTO approval_requests (\"proposalId\",\"proposalHash\",\"actionType\",\"executionId\",\"logicalStepId\",\"attemptNumber\",\"targetAgent\",\"targetExecutor\",status,\"expiresAt\") VALUES (?,?,?,?,?,?,?,?, 'PENDING',?) ON CONFLICT (\"proposalId\") DO NOTHING",p.get("proposalId"),p.get("hash"),p.get("actionType"),s.get("executionId"),Json.text(s,"logicalStepId",""),Json.integer(s,"attemptNumber",1),Json.get(target,"agent"),Json.get(target,"executor"),due);ObjectNode row=t.one("SELECT * FROM approval_requests WHERE \"proposalId\"=?",p.get("proposalId"));if(row==null)throw new IllegalStateException("Approval request produced no row");return row;}
    public ObjectNode approve(String id,Connection c,JsonNode note){String bounded=Approval.boundedApprovalNote(note);return tx(c,t->{ObjectNode preview=t.one("SELECT * FROM approval_requests WHERE \"proposalId\"=?",id);if(preview!=null&&"plan_patch".equals(Json.text(preview,"actionType")))t.one("SELECT id FROM executions WHERE id=?::uuid FOR UPDATE",preview.get("executionId"));ObjectNode r=lock(t,id);if(!"PENDING".equals(Json.text(r,"status")))return r;if("plan_patch".equals(Json.text(r,"actionType"))){r=decide(t,r,"APPROVED",bounded==null?"approved":bounded,Instant.now());ObjectNode outcome=plans.activateWithManager(t.connection(),id.replaceFirst("^plan:",""));return t.update("approval_requests",Json.text(r,"id"),Json.object("decisionNote",bounded!=null?bounded:"ACCEPTED".equals(Json.text(outcome,"decision"))?"approved; plan activated":"approved; proposal "+Json.text(outcome,"decision")+": "+Json.text(outcome,"reason")));}
        ObjectNode attempt=attempt(t,r),step=step(t,r);if(!"WAITING".equals(Json.text(attempt,"status")))return decide(t,r,"APPROVED",bounded==null?"attempt already terminal":bounded,Instant.now());ObjectNode revision=t.one("SELECT * FROM execution_plan_revisions WHERE id=?::uuid",attempt.get("planRevisionId"));ObjectNode config=config(revision,Json.text(step,"stepId"));if("observed".equals(Json.text(config,"delegation"))&&(supportsObserved==null||!supportsObserved.test(Json.text(config,"agent")))){fail(t,attempt,step,config,"Runtime does not support observed delegation");return decide(t,r,"APPROVED",bounded==null?"runtime capability changed; dispatch not granted":bounded,Instant.now());}
        if(config.hasNonNull("budget")){Savepoint checkpoint=t.connection().setSavepoint();try{ObjectNode account=budget.ensureExecutionAccount(t.connection(),Json.text(r,"executionId"),revision.path("plan").get("budget"),config.get("budget"));budget.reserveForAttempt(t.connection(),Json.object("executionId",r.get("executionId"),"logicalStepId",step.get("id"),"attemptNumber",attempt.get("attemptNumber"),"invocationId",attempt.get("invocationId"),"accountId",account.get("id"),"budget",config.get("budget")));t.connection().releaseSavepoint(checkpoint);}catch(AuthorityError error){t.connection().rollback(checkpoint);fail(t,attempt,step,config,"Budget reservation failed: "+error.code);return decide(t,r,"APPROVED",bounded==null?"budget insufficient":bounded,Instant.now());}}
        t.update("step_attempts",Json.text(attempt,"id"),Json.object("status","CREATED"));t.update("step_executions",Json.text(step,"id"),Json.object("status","RUNNING"));ObjectNode invocation=Json.object("schemaVersion","1","invocationId",attempt.get("invocationId"),"executionId",r.get("executionId"),"stepExecutionId",step.get("id"),"stepId",config.get("id"),"target",Json.object("agent",config.get("agent")),"input",attempt.get("inputSnapshot"),"attempt",attempt.get("attemptNumber"),"createdAt",Instant.now().toString(),"trace",Json.object("traceId",r.get("executionId"),"correlationId",attempt.get("invocationId")),"metadata",Json.object("orchestration",Json.object("maxAttempts",Json.integer(config,"retries",0)+1)));if(attempt.hasNonNull("deadlineAt"))invocation.set("deadlineAt",attempt.get("deadlineAt"));if(attempt.hasNonNull("contextSnapshot"))invocation.set("context",attempt.get("contextSnapshot"));if(workspaceMetadata!=null){JsonNode workspace=workspaceMetadata.get(t.connection(),Json.text(r,"executionId"));if(workspace!=null&&!workspace.isNull())((ObjectNode)invocation.get("metadata")).set("tenvyr",workspace);}JsonNode executor=attempt.path("executorSnapshot");if(executor.hasNonNull("connection")){JsonNode ref=executor.get("connection");invocation.set("connection",Json.object("connectionId",ref.get("connectionId"),"revisionNumber",ref.get("revisionNumber"),"configHash",ref.get("configHash")));}if(executor.hasNonNull("requestedModelId"))invocation.set("requestedModelId",executor.get("requestedModelId"));t.insert("dispatch_outbox",Json.object("stepAttemptId",attempt.get("id"),"invocation",invocation));return decide(t,r,"APPROVED",bounded,Instant.now());});}
    public ObjectNode deny(String id,Connection c,JsonNode note){String bounded=Approval.boundedApprovalNote(note);return tx(c,t->{ObjectNode r=lock(t,id);if(!"PENDING".equals(Json.text(r,"status")))return r;terminalize(t,r,"Approval denied");return decide(t,r,"DENIED",bounded,Instant.now());});}
    public ObjectNode expire(String id,Connection c,Instant now){return tx(c,t->{ObjectNode r=lock(t,id);if(!"PENDING".equals(Json.text(r,"status"))||Instant.parse(Json.text(r,"expiresAt")).isAfter(now))return null;terminalize(t,r,"Approval expired");return decide(t,r,"EXPIRED",Json.text(r,"decisionNote"),now);});}
    public int expireDue(Connection c,Instant now,int limit){return tx(c,t->{List<ObjectNode> due=t.query("SELECT * FROM approval_requests WHERE status='PENDING' AND \"expiresAt\"<=? ORDER BY \"expiresAt\",id LIMIT ? FOR UPDATE SKIP LOCKED",now,Math.max(0,Math.min(1000,limit)));for(ObjectNode r:due){terminalize(t,r,"Approval expired");decide(t,r,"EXPIRED",Json.text(r,"decisionNote"),now);}return due.size();});}
    private void terminalize(Db t,ObjectNode r,String reason){if("plan_patch".equals(Json.text(r,"actionType"))){t.execute("UPDATE plan_proposals SET status='REJECTED',\"decisionReason\"=?,\"decidedAt\"=? WHERE id=?::uuid AND status='PENDING'",reason,Instant.now(),Json.text(r,"proposalId").replaceFirst("^plan:",""));return;}ObjectNode a=attempt(t,r),s=step(t,r);ObjectNode revision=t.one("SELECT * FROM execution_plan_revisions WHERE id=?::uuid",a.get("planRevisionId"));fail(t,a,s,config(revision,Json.text(s,"stepId")),reason);}
    private void fail(Db t,ObjectNode a,ObjectNode s,ObjectNode config,String reason){Instant now=Instant.now();int changed=t.execute("UPDATE step_attempts SET status='FAILED',\"terminalAt\"=?,result=NULL,error=?,\"terminationReason\"=? WHERE id=?::uuid AND status='WAITING'",now,reason,reason,a.get("id"));if(changed!=1)return;boolean retry="retry".equals(Json.text(config,"onFailure"))&&Json.integer(a,"attemptNumber",1)<=Json.integer(config,"retries",0);int stepChanged=t.execute("UPDATE step_executions SET status=?,error=?,\"endTime\"=?,\"nextAttemptAt\"=?,\"rowVersion\"=\"rowVersion\"+1,\"updatedAt\"=now() WHERE id=?::uuid AND status='WAITING'",retry?"RETRYING":"FAILED",reason,retry?null:now,retry?now:null,s.get("id"));if(!retry&&!"continue".equals(Json.text(config,"onFailure"))&&stepChanged==1)t.execute("UPDATE executions SET status='FAILED',\"endTime\"=?,\"terminationReason\"=?,output=?,\"rowVersion\"=\"rowVersion\"+1,\"updatedAt\"=now() WHERE id=?::uuid AND status='RUNNING'",now,reason,Json.object("failedStep",config.get("id"),"error",reason),a.get("executionId"));}
    private static ObjectNode config(JsonNode revision,String id){if(revision!=null)for(JsonNode s:revision.path("plan").path("steps"))if(id.equals(Json.text(s,"id")))return (ObjectNode)s;throw new AuthorityError("POLICY_CONFIG_INVALID","Frozen step config not found");}
    private ObjectNode lock(Db t,String id){ObjectNode r=t.one("SELECT * FROM approval_requests WHERE \"proposalId\"=? FOR UPDATE",id);if(r==null)throw new AuthorityError("POLICY_CONFIG_INVALID","Approval request not found");return r;}
    private ObjectNode attempt(Db t,JsonNode r){ObjectNode a=t.one("SELECT * FROM step_attempts WHERE \"executionId\"=?::uuid AND \"logicalStepId\"=?::uuid AND \"attemptNumber\"=? FOR UPDATE",r.get("executionId"),r.get("logicalStepId"),r.get("attemptNumber"));if(a==null)throw new AuthorityError("POLICY_CONFIG_INVALID","Approval attempt not found");return a;}
    private ObjectNode step(Db t,JsonNode r){ObjectNode s=t.one("SELECT * FROM step_executions WHERE id=?::uuid AND \"executionId\"=?::uuid FOR UPDATE",r.get("logicalStepId"),r.get("executionId"));if(s==null)throw new AuthorityError("POLICY_CONFIG_INVALID","Approval step not found");return s;}
    private ObjectNode decide(Db t,JsonNode r,String status,String note,Instant now){return t.update("approval_requests",Json.text(r,"id"),Json.object("status",status,"decidedAt",now.toString(),"decisionNote",note));}
}
